{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Orientin, the closest high-similarity analogue sharing the C-glucosyl polyphenol scaffold and catechol pattern, showed only low brain levels after intravenous administration in rats and was judged impermeable due to high polarity, directly supporting poor CNS access for the similarly polar xanthone C-glucoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin, a closely related C-glucosyl flavone lacking the catechol moiety, was detected in rat brain after intravenous dosing and labeled permeable, providing some contradictory evidence that C-glucosyl polyphenols can cross the BBB; however, its lower polarity and absence of the catechol reduce transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hyperoside, an O-galactosylated flavonol, was detected in rat brain after oral administration, but its lower similarity and different glycoside linkage make it only weakly transferable and insufficient to override the close negative analogue.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest transferable evidence is the close analogue orientin, which is poorly brain-permeable after IV dosing because of high polarity; the query shares the same C-glucosyl polyphenol architecture, high polar surface area, and catechol functionality. Although isovitexin shows some brain transfer, its lower polarity and structural divergence make it less relevant. Overall, the evidence points to inadequate CNS access.",
  "evidence_gaps": [
    "No direct mangiferin brain or CSF concentration data are provided.",
    "No brain-to-plasma ratio or unbound brain exposure is available for the closest analogues.",
    "Efflux transporter involvement (e.g., P-gp/BCRP) for the query is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

